const crypto = require('crypto');
const dataId = '1234567890';
const requestId = '11111111-1111-4111-8111-111111111111';
const ts = Math.floor(Date.now() / 1000).toString();
const msg = `id:${dataId};request-id:${requestId};ts:${ts};`;
const v1 = crypto.createHmac('sha256', 'dev-secret-local').update(msg).digest('hex');
insomnia.environment.set('x_request_id', requestId);
insomnia.environment.set('x_signature', `ts=${ts},v1=${v1}`);
